using System;using KerbalDriftAgency;class LightingCoreTests{static int n;static void Check(bool b,string s){n++;if(!b)throw new Exception(s);Console.WriteLine("PASS "+s);}static double S(string s,bool h=false,bool hi=false,bool b=false,bool r=false,int i=0,double t=0,bool run=false){return LightingCore.Signal(s,h,hi,b,r,i,t,run);}static void Main(){Check(S("lowbeam")==0&&S("highbeam",hi:true)==0,"high-beam preference cannot turn off headlights on");Check(S("lowbeam",h:true)==1&&S("highbeam",h:true)==0,"low beam operates alone");Check(S("lowbeam",h:true,hi:true)==1&&S("highbeam",h:true,hi:true)==1,"high-beam mode retains running low lamps");Check(S("brake",b:true)==1&&S("brake",h:true)==0,"brake lamps follow driver braking independently of headlights");Check(S("reverse",r:true)==1&&S("reverse")==0,"reverse lamps follow reverse selection");Check(S("signal_L",i:1)==1&&S("signal_R",i:1)==0,"left signal does not trigger right");Check(S("signal_R",i:2)==1&&S("signal_L",i:2)==0,"right signal does not trigger left");Check(S("signal_L",i:3)==S("signal_R",i:3)&&S("signal_L",i:3)==1,"hazards blink together");Check(S("signal_L",i:3,t:.6)==0&&S("signal_R",i:3,t:.6)==0&&S("signal_L",i:3,t:.85)==1,"blink cycle has an off interval and repeats");Check(S("ignitionLevel",run:true)==1&&S("ignitionLevel")==0,"available ignition glow follows engine state");Check(S("unsupported",h:true,b:true)==0,"unsupported source functions stay off");Console.WriteLine("PASS total="+n);}}
